CREATE TABLE IF NOT EXISTS services (id INTEGER PRIMARY KEY, category TEXT NOT NULL, name TEXT NOT NULL, minutes INTEGER NOT NULL, price INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS openings (id INTEGER PRIMARY KEY, day TEXT NOT NULL, start_min INTEGER NOT NULL, end_min INTEGER NOT NULL, CHECK(start_min < end_min));
CREATE INDEX IF NOT EXISTS openings_day ON openings(day);
CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, phone TEXT NOT NULL UNIQUE, name TEXT NOT NULL, note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY, day TEXT NOT NULL, start_min INTEGER NOT NULL, end_min INTEGER NOT NULL, service_id INTEGER NOT NULL, service_name TEXT NOT NULL, price INTEGER NOT NULL, client_name TEXT NOT NULL, phone TEXT NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'confirmed', created_at TEXT NOT NULL, client_id INTEGER, channel TEXT, channel_user_id TEXT);
CREATE INDEX IF NOT EXISTS bookings_day ON bookings(day,status);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO settings (key,value) VALUES ('buffer_minutes','10'),('address',''),('contact','');
CREATE TABLE IF NOT EXISTS notifications (booking_id INTEGER NOT NULL, kind TEXT NOT NULL, sent_at TEXT NOT NULL, PRIMARY KEY(booking_id,kind));
CREATE TABLE IF NOT EXISTS daily_digests (day TEXT PRIMARY KEY, sent_at TEXT NOT NULL);
